insert into recipes (id, name, kind, base, tags, glasses, garnishes, history, description, instructions, mood) values
  ('classic-margarita', 'Classic Margarita', 'cocktail', 'Tequila', array['Citrus']::text[], array['Coupe', 'Rocks']::text[], array['Half salt rim & lime wheel', 'Salt rim & lime wedge']::text[], 'Origin debated between Mexico and Texas in 1930s', 'Citrusy tequila favorite', 'Rim half of a chilled coupe with salt. Add all ingredients to shaker with ice. Shake vigorously 10 sec. Strain into the coupe (or a salt-rimmed rocks glass over fresh ice). Garnish with a lime wheel.', 'Party'),
  ('tequila-sour', 'Tequila Sour', 'cocktail', 'Tequila', array['Citrus']::text[], array['Rocks', 'Coupe']::text[], array['Lemon wheel', 'Lime wheel']::text[], 'A classic Tequila cocktail developed as part of traditional bar culture.', 'A balanced tequila-based cocktail made with simple, well-rounded ingredients.', 'Add all ingredients to shaker with ice. Shake vigorously 10 sec. Strain into rocks glass over ice. Optional: garnish with a lime wheel.', 'Energised'),
  ('tequila-old-fashioned', 'Tequila Old Fashioned', 'cocktail', 'Tequila', array['Citrus']::text[], array['Rocks']::text[], array['Lime peel', 'Orange peel']::text[], 'A modern riff on the 19th-century Old Fashioned, substituting tequila for whiskey.', 'A balanced tequila-based cocktail made with simple, well-rounded ingredients.', 'Add syrup and bitters to mixing glass. Add Tequila and ice. Stir 30 sec until chilled. Strain over large ice cube in rocks glass. Garnish with lime peel.', 'Bold'),
  ('gin-martini', 'Gin Martini', 'cocktail', 'Gin', array['Signature']::text[], array['Martini', 'Nick & Nora', 'Coupe']::text[], array['Lemon twist', 'Green olive', 'Lime twist']::text[], 'One of the most iconic cocktails of the early 20th century, associated with elegance and refinement.', 'A balanced gin-based cocktail made with simple, well-rounded ingredients.', 'Chill martini glass with ice water. Add gin and vermouth to mixing glass with ice. Stir 30 sec. Strain into chilled martini glass. Garnish with a lemon twist or a green olive.', 'Bold'),
  ('gimlet', 'Gimlet', 'cocktail', 'Gin', array['Classic']::text[], array['Coupe', 'Martini']::text[], array['Lime wheel', 'Lime twist']::text[], 'A classic Gin cocktail developed as part of traditional bar culture.', 'A balanced gin-based cocktail made with simple, well-rounded ingredients.', 'Add all ingredients to shaker with ice. Shake vigorously 15 sec. Double strain into chilled coupe glass. Garnish with lime wheel.', 'Energised'),
  ('bee-s-knees', 'Bee''s Knees', 'cocktail', 'Gin', array['Classic']::text[], array['Coupe']::text[], array['Lemon twist', 'Orange twist']::text[], 'A classic Gin cocktail developed as part of traditional bar culture.', 'A balanced gin-based cocktail made with simple, well-rounded ingredients.', 'Add all ingredients to shaker with ice. Shake vigorously 15 sec. Double strain into chilled coupe. Garnish with lemon peel. Note: Use honey syrup instead of simple syrup if available.', 'Romantic'),
  ('french-75', 'French 75', 'cocktail', 'Gin', array['Classic']::text[], array['Flute', 'Coupe']::text[], array['Lemon twist']::text[], 'Created during World War I and named after a French field gun, symbolizing its strength and sparkle.', 'A balanced gin-based cocktail made with simple, well-rounded ingredients.', 'Add gin, lemon juice, and syrup to shaker with ice. Shake 10 sec. Strain into champagne flute. Top with chilled Prosecco. Garnish with lemon twist.', 'Romantic'),
  ('mimosa', 'Mimosa', 'cocktail', 'Prosecco', array['Refreshing', 'Aperitif']::text[], array['Flute']::text[], array['Orange twist', 'Orange slice']::text[], 'Popularized in early 20th-century France, especially as a brunch cocktail.', 'A balanced prosecco-based cocktail made with simple, well-rounded ingredients.', 'Chill champagne flute. Pour OJ into flute first. Slowly top with chilled Prosecco. Gently stir once. Garnish with an orange twist or slice.', 'Party'),
  ('rob-roy', 'Rob Roy', 'cocktail', 'Whisky', array['Whisky', 'Spirit-Forward']::text[], array['Coupe', 'Martini']::text[], array['Cocktail cherry', 'Lemon twist']::text[], 'A classic Scotch cocktail developed as part of traditional bar culture.', 'A balanced scotch-based cocktail made with simple, well-rounded ingredients.', 'Add all ingredients to mixing glass with ice. Stir 30 sec until well chilled. Strain into chilled coupe or martini glass. Garnish with a cocktail cherry or a lemon twist.', 'Bold'),
  ('scotch-sour', 'Scotch Sour', 'cocktail', 'Whisky', array['Whisky', 'Spirit-Forward']::text[], array['Rocks', 'Coupe']::text[], array['Lemon wheel & cherry', 'Lemon wheel']::text[], 'A classic Scotch cocktail developed as part of traditional bar culture.', 'A balanced scotch-based cocktail made with simple, well-rounded ingredients.', 'Add all ingredients to shaker with ice. Shake vigorously 15 sec. Strain into rocks glass over ice. Garnish with lemon wheel and cherry if available.', 'Cosy'),
  ('old-fashioned', 'Old Fashioned', 'cocktail', 'Whisky', array['Signature']::text[], array['Rocks']::text[], array['Orange peel & cherry', 'Orange peel', 'Lemon peel']::text[], 'One of the earliest documented cocktails, dating to the early 19th century. The name emerged in the 1880s to distinguish it from newer, more elaborate drinks - literally the "old-fashioned" way to mix whisky.', 'The original cocktail - a spirit-forward pour of whisky softened by a whisper of sugar and bitters over a large cube.', 'Add syrup and bitters to mixing glass. Add whisky and ice. Stir 30 sec. Strain over large ice cube in rocks glass. Express an orange peel over the glass and drop it in with a cocktail cherry.', 'Cosy'),
  ('penicillin', 'Penicillin', 'cocktail', 'Whisky', array['Whisky', 'Spirit-Forward']::text[], array['Rocks']::text[], array['Candied ginger', 'Lemon peel']::text[], 'A classic Scotch cocktail developed as part of traditional bar culture.', 'A balanced scotch-based cocktail made with simple, well-rounded ingredients.', 'Add Scotch, lemon juice, and syrup to shaker with ice. Shake vigorously 15 sec. Strain into rocks glass over ice. Add a dash of cocoa bitters on top. Garnish with candied ginger. Note: Traditionally uses honey-ginger syrup "” demerara is a solid substitute.', 'Bold'),
  ('godfather', 'Godfather', 'cocktail', 'Whisky', array['Classic']::text[], array['Rocks']::text[], array['Orange peel']::text[], 'A classic Scotch cocktail developed as part of traditional bar culture.', 'A balanced scotch-based cocktail made with simple, well-rounded ingredients.', 'Fill rocks glass with ice. Pour Scotch over ice. Add Amaretto. Stir gently to combine. Garnish with orange peel.', 'Bold'),
  ('amaretto-sour', 'Amaretto Sour', 'cocktail', 'Amaretto', array['Nutty', 'Sweet']::text[], array['Rocks', 'Coupe']::text[], array['Lemon wheel & cherry', 'Lemon wheel']::text[], 'A classic Amaretto cocktail developed as part of traditional bar culture.', 'A balanced amaretto-based cocktail made with simple, well-rounded ingredients.', 'Add all ingredients to shaker with ice. Shake vigorously 15 sec. Strain into rocks glass over ice. Garnish with lemon slice.', 'Curious'),
  ('disaronno-fizz', 'Disaronno Fizz', 'cocktail', 'Amaretto', array['Nutty', 'Sweet']::text[], array['Highball']::text[], array['Lemon wedge', 'Lemon wheel']::text[], 'A classic Amaretto cocktail developed as part of traditional bar culture.', 'A balanced amaretto-based cocktail made with simple, well-rounded ingredients.', 'Shake Amaretto, lemon juice, and syrup with ice. Strain into highball glass over ice. Top with Prosecco. Stir gently. Garnish with lemon wedge.', 'Chill'),
  ('vodka-sour', 'Vodka Sour', 'cocktail', 'Vodka', array['Classic']::text[], array['Rocks', 'Coupe']::text[], array['Lemon wheel', 'Lemon wheel & cherry']::text[], 'A classic Vodka cocktail developed as part of traditional bar culture.', 'A balanced vodka-based cocktail made with simple, well-rounded ingredients.', 'Add all ingredients to shaker with ice. Shake vigorously 15 sec. Strain into rocks glass over ice. Garnish with lemon wheel.', 'Energised'),
  ('kamikaze', 'Kamikaze', 'cocktail', 'Vodka', array['Classic']::text[], array['Martini', 'Coupe', 'Shot glass']::text[], array['Lime wheel', 'Lime wedge']::text[], 'A classic Vodka cocktail developed as part of traditional bar culture.', 'A balanced vodka-based cocktail made with simple, well-rounded ingredients.', 'Add all ingredients to shaker with ice. Shake vigorously 15 sec. Strain into chilled martini glass or shot glasses. Garnish with lime wheel.', 'Party'),
  ('pomegranate-martini', 'Pomegranate Martini', 'cocktail', 'Vodka', array['Classic']::text[], array['Martini', 'Coupe']::text[], array['Lime twist', 'Pomegranate seeds']::text[], 'A classic Vodka cocktail developed as part of traditional bar culture.', 'A balanced vodka-based cocktail made with simple, well-rounded ingredients.', 'Add all ingredients to shaker with ice. Shake vigorously 15 sec. Double strain into chilled martini glass. Garnish with lime twist or pomegranate seeds.', 'Romantic'),
  ('screwdriver', 'Screwdriver', 'cocktail', 'Vodka', array['Classic']::text[], array['Highball']::text[], array['Orange slice', 'Orange wedge']::text[], 'A classic Vodka cocktail developed as part of traditional bar culture.', 'A balanced vodka-based cocktail made with simple, well-rounded ingredients.', 'Fill highball glass with ice. Pour Vodka over ice. Top with fresh OJ. Stir gently. Garnish with orange slice.', 'Party'),
  ('tequila-sunrise', 'Tequila Sunrise', 'cocktail', 'Tequila', array['Citrus']::text[], array['Highball', 'Collins']::text[], array['Orange slice', 'Orange slice & cherry', 'Orange twist']::text[], 'A classic Tequila cocktail developed as part of traditional bar culture.', 'A balanced tequila-based cocktail made with simple, well-rounded ingredients.', 'Fill highball glass with ice. Pour Tequila and OJ over ice and stir. Slowly pour pomegranate juice down the side of the glass. Do NOT stir "” let it sink for sunrise effect. Garnish with orange slice.', 'Party'),
  ('white-lady', 'White Lady', 'cocktail', 'Gin', array['Classic']::text[], array['Coupe', 'Martini']::text[], array['Lemon twist']::text[], 'A classic Gin cocktail developed as part of traditional bar culture.', 'A balanced gin-based cocktail made with simple, well-rounded ingredients.', 'Add all ingredients to shaker with ice. Shake hard 15 sec. Double strain into chilled coupe. Garnish with lemon twist.', 'Romantic'),
  ('vodka-martini', 'Vodka Martini', 'cocktail', 'Vodka', array['Classic']::text[], array['Martini', 'Nick & Nora']::text[], array['Lemon twist', 'Green olive']::text[], 'A classic Vodka cocktail developed as part of traditional bar culture.', 'A balanced vodka-based cocktail made with simple, well-rounded ingredients.', 'Chill martini glass. Stir ingredients with ice 30 sec. Strain into chilled glass. Garnish with a lemon twist or a green olive.', 'Bold'),
  ('vodka-gimlet', 'Vodka Gimlet', 'cocktail', 'Vodka', array['Classic']::text[], array['Coupe', 'Martini']::text[], array['Lime wheel']::text[], 'A classic Vodka cocktail developed as part of traditional bar culture.', 'A balanced vodka-based cocktail made with simple, well-rounded ingredients.', 'Shake all ingredients with ice. Strain into chilled coupe. Garnish with lime wheel.', 'Energised'),
  ('lemon-drop', 'Lemon Drop', 'cocktail', 'Vodka', array['Signature']::text[], array['Coupe', 'Martini']::text[], array['Sugar rim & lemon twist', 'Sugar rim & lemon wheel']::text[], 'A classic Vodka cocktail developed as part of traditional bar culture.', 'A balanced vodka-based cocktail made with simple, well-rounded ingredients.', 'Shake all ingredients with ice. Strain into sugar-rimmed coupe. Garnish with lemon peel.', 'Party'),
  ('vesper-blanc-style', 'Vesper (Blanc Style)', 'cocktail', 'Gin', array['Classic']::text[], array['Martini', 'Coupe']::text[], array['Lemon twist']::text[], 'A classic Gin cocktail developed as part of traditional bar culture.', 'A balanced gin-based cocktail made with simple, well-rounded ingredients.', 'Stir all ingredients with ice until very cold. Strain into chilled martini glass. Garnish with lemon twist.', 'Bold'),
  ('tequila-martini', 'Tequila Martini', 'cocktail', 'Tequila', array['Citrus']::text[], array['Coupe', 'Martini']::text[], array['Lime twist', 'Green olive']::text[], 'A classic Tequila cocktail developed as part of traditional bar culture.', 'A balanced tequila-based cocktail made with simple, well-rounded ingredients.', 'Stir with ice 30 sec. Strain into chilled coupe or martini glass. Garnish with lime twist.', 'Bold'),
  ('blanc-manhattan-tequila', 'Blanc Manhattan (Tequila)', 'cocktail', 'Tequila', array['Citrus']::text[], array['Coupe', 'Nick & Nora']::text[], array['Lime peel', 'Lemon peel']::text[], 'A classic Tequila cocktail developed as part of traditional bar culture.', 'A balanced tequila-based cocktail made with simple, well-rounded ingredients.', 'Stir all ingredients with ice. Strain into coupe. Garnish with lime or lemon peel.', 'Curious'),
  ('godmother', 'Godmother', 'cocktail', 'Vodka', array['Classic']::text[], array['Rocks']::text[], array['Lemon peel']::text[], 'A classic Vodka cocktail developed as part of traditional bar culture.', 'A balanced vodka-based cocktail made with simple, well-rounded ingredients.', 'Build ingredients over ice in rocks glass. Stir gently. Garnish with lemon peel.', 'Cosy'),
  ('amaretto-old-fashioned', 'Amaretto Old Fashioned', 'cocktail', 'Amaretto', array['Nutty', 'Sweet']::text[], array['Rocks']::text[], array['Lemon peel', 'Lemon peel & cherry']::text[], 'A classic Amaretto cocktail developed as part of traditional bar culture.', 'A balanced amaretto-based cocktail made with simple, well-rounded ingredients.', 'Add bitters and amaretto to rocks glass with ice. Stir gently. Express lemon peel over glass.', 'Curious'),
  ('pomegranate-spritz', 'Pomegranate Spritz', 'cocktail', 'Prosecco', array['Refreshing', 'Aperitif']::text[], array['Wine glass']::text[], array['Lime wheel', 'Pomegranate seeds']::text[], 'A classic Prosecco cocktail developed as part of traditional bar culture.', 'A balanced prosecco-based cocktail made with simple, well-rounded ingredients.', 'Fill wine glass with ice. Add juice and syrup. Top with Prosecco. Light stir. Garnish with lime wheel.', 'Chill'),
  ('gin-pomegranate-collins-soda-free', 'Gin & Pomegranate Collins (Soda-free)', 'cocktail', 'Gin', array['Classic']::text[], array['Collins', 'Highball']::text[], array['Lemon wheel', 'Pomegranate seeds']::text[], 'A classic Gin cocktail developed as part of traditional bar culture.', 'A balanced gin-based cocktail made with simple, well-rounded ingredients.', 'Shake all ingredients with ice. Strain into tall glass over ice. Garnish with lemon wheel.', 'Energised'),
  ('scotch-amaretto-sour', 'Scotch & Amaretto Sour', 'cocktail', 'Whisky', array['Whisky', 'Spirit-Forward']::text[], array['Rocks']::text[], array['Lemon peel', 'Lemon wheel & cherry']::text[], 'A classic Scotch cocktail developed as part of traditional bar culture.', 'A balanced scotch-based cocktail made with simple, well-rounded ingredients.', 'Shake with ice. Strain into rocks glass over ice. Garnish with lemon peel.', 'Cosy'),
  ('negroni', 'Negroni', 'cocktail', 'Gin', array['Italian Classic', 'Aperitif']::text[], array['Rocks']::text[], array['Orange half-wheel', 'Orange peel']::text[], 'Created in Florence, Italy in 1919 when Count Camillo Negroni asked his bartender to strengthen his Americano by swapping soda for gin. An instant classic that has become one of the world''s most ordered cocktails.', 'The iconic bittersweet trinity — equal parts gin, Campari, and vermouth. Empress 1908''s floral botanicals bloom against Campari''s herbal bitterness. Note: Traditional recipe uses sweet red vermouth; Dolin Dry/Blanc makes it lighter and more aromatic.', 'Add all ingredients to a mixing glass with ice. Stir for 30 seconds until well chilled. Strain into a rocks glass over a large ice cube. Garnish with an orange half-wheel (or express an orange peel over the drink).', 'Bold'),
  ('americano', 'Americano', 'cocktail', 'Campari', array['Italian Classic', 'Aperitif']::text[], array['Rocks', 'Highball']::text[], array['Orange half-wheel & lemon twist', 'Orange slice']::text[], 'Created in the 1860s by Gaspare Campari at his Caffè Camparino in Milan. The predecessor to the Negroni — Count Negroni famously asked for gin to replace the soda. A low-ABV Italian aperitivo staple.', 'Light, bubbly, and gently bitter — Campari''s herbal bite softened by vermouth and lifted by soda. The perfect pre-dinner drink. Note: Traditional recipe uses sweet red vermouth; Dolin Dry/Blanc makes it drier and more floral.', 'Fill a rocks glass (or highball) with ice. Add Campari and vermouth. Top with chilled soda. Stir gently once. Garnish with an orange half-wheel and a lemon twist.', 'Chill'),
  ('dark-rum-manhattan', 'Dark Rum Manhattan', 'cocktail', 'Rum', array['Classic']::text[], array['Coupe', 'Martini']::text[], array['Lime peel', 'Orange peel', 'Cocktail cherry']::text[], 'Rum-vermouth cocktails predate Prohibition and were common in port cities where rum was more accessible than whiskey, making this a natural Caribbean adaptation of the Manhattan.', 'A rich, spirit-forward cocktail showcasing aged rum’s molasses depth softened by herbal vermouth and warming bitters.', 'Add all ingredients to a mixing glass with ice. Stir for 30 seconds until well chilled. Strain into a chilled coupe or martini glass. Garnish with expressed lime peel.', 'Cosy'),
  ('kingston-highball', 'Kingston Highball', 'cocktail', 'Rum', array['Refreshing', 'Highball']::text[], array['Highball']::text[], array['Lime wedge']::text[], 'Rum-ginger combinations are staples in Caribbean drinking culture, prized for their balance of spice and refreshment.', 'A lively, refreshing highball with spicy ginger, bright citrus, and rich aged rum backbone.', 'Build rum, lime, and syrup in a highball glass over ice. Top with ginger beer. Give one gentle stir. Garnish with lime wedge.', 'Party'),
  ('rum-pomegranate-spritz', 'Rum Pomegranate Spritz', 'cocktail', 'Rum', array['Sparkling', 'Aperitif']::text[], array['Wine glass']::text[], array['Lime wheel', 'Pomegranate seeds']::text[], 'Spritz-style cocktails have their roots in Europe but have been widely adapted with different base spirits in contemporary home and craft bars.', 'A light, elegant spritz combining dark rum’s depth with bright fruit and sparkling wine.', 'Add rum, juice, and syrup to a wine glass with ice. Top with Prosecco (and a splash of soda if desired). Gently stir. Garnish with lime wheel', 'Chill'),
  ('blossom-of-love', 'Blossom of Love', 'cocktail', 'Gin', array['Signature']::text[], array['Coupe', 'Martini']::text[], array['Edible rose petal', 'Lemon twist']::text[], 'Inspired by the classic martini and modern floral cocktails, this variation was adapted to create a softer, visually striking Valentine-themed drink using color-changing gin.', 'A smooth, floral martini with a gentle citrus lift and a blush pink hue, offering a balanced, slightly sweet, and elegant sipping experience', 'Chill a coupe or martini glass with ice water. Add Empress gin, Dolin Dry, lime juice, and simple syrup to a mixing glass with ice. Stir for 30 seconds until well chilled. Strain into the chilled glass. Watch the Empress gin bloom into a soft blush pink. Garnish with an edible rose petal or a lemon twist.', 'Romantic'),
  ('rose-empress-fizz', 'Rose Empress Fizz', 'cocktail', 'Gin', array['Signature']::text[], array['Wine glass', 'Flute']::text[], array['Edible rose petal', 'Lemon twist']::text[], 'A home-bar original created to showcase the striking color shift of Empress 1908 Gin against Rooh Afza - the iconic rose-cardamom-kewra syrup from South Asia - lifted with citrus and Prosecco. A fusion of British gin tradition and subcontinental flavour.', 'A floral, blush-toned fizz where rose and cooling botanicals from Rooh Afza soften the juniper of Empress gin, brightened with fresh lemon and finished with lively Prosecco bubbles. Elegant, aromatic, and romantic.', 'Shake gin + Rooh Afza + lemon with ice → strain into wine glass → top with chilled Prosecco. Garnish with an edible rose petal.', 'Romantic'),
  ('mojito', 'Mojito', 'cocktail', 'Rum', array['Classic', 'Refreshing']::text[], array['Highball', 'Collins']::text[], array['Mint sprig & lime wheel']::text[], 'Born in Havana, Cuba in the 16th century, the mojito was reputedly a favourite of Ernest Hemingway at La Bodeguita del Medio.', 'Cuba''s most iconic cocktail - bright lime, fresh mint, and aged rum lifted by a long soda top. Effortlessly refreshing.', 'Muddle mint leaves with lime juice and syrup in a highball glass. Fill with crushed ice. Pour rum over ice. Top with soda. Stir gently from the bottom. Garnish with a mint sprig and lime wheel.', 'Fresh'),
  ('dark-rum-daiquiri', 'Dark Rum Daiquiri', 'cocktail', 'Rum', array['Classic', 'Citrus']::text[], array['Coupe']::text[], array['Lime wheel']::text[], 'The daiquiri originated in the iron-mining town of Daiquirí, Cuba in the early 1900s, popularised by American engineers and later by Ernest Hemingway.', 'Three ingredients, perfectly balanced - aged rum''s molasses richness brightened with fresh lime and a whisper of sweetness.', 'Add all ingredients to a shaker with ice. Shake hard for 12 seconds. Double strain into a chilled coupe. Garnish with a lime wheel.', 'Chill'),
  ('rum-old-fashioned', 'Rum Old Fashioned', 'cocktail', 'Rum', array['Spirit-Forward', 'Classic']::text[], array['Rocks']::text[], array['Orange peel']::text[], 'A rum riff on the 1880s Old Fashioned, popular in Caribbean bars where aged rum is as revered as whiskey in the American South.', 'Slow, rich, and complex - molasses-forward rum dressed with caramel syrup and warming bitters over a single large cube.', 'Add syrup and bitters to a rocks glass. Add rum. Fill with a large ice cube. Stir 20 rotations to combine and chill. Express an orange peel over the glass and drop in.', 'Cosy'),
  ('tom-collins', 'Tom Collins', 'cocktail', 'Gin', array['Classic', 'Highball']::text[], array['Collins', 'Highball']::text[], array['Lemon slice & cherry', 'Lemon slice']::text[], 'Named after an 1870s New York prank - the ''Tom Collins hoax'' - where people were told a man named Tom Collins was speaking badly about them. The cocktail emerged as the joke spread.', 'A tall, refreshing classic - gin, citrus, and sugar topped with soda. The Empress gin adds a stunning indigo colour.', 'Combine gin, lemon juice, and syrup in a shaker with ice. Shake 10 seconds. Strain into a tall Collins glass over ice. Top with soda. Gently stir. Garnish with a lemon slice and a cherry.', 'Fresh'),
  ('gin-fizz', 'Gin Fizz', 'cocktail', 'Gin', array['Classic', 'Effervescent']::text[], array['Highball']::text[], array['Lemon wheel', 'Lemon twist']::text[], 'The Fizz family of cocktails dates to the 1870s, popularised in Jerry Thomas''s bartender guides. The gin fizz is one of the simplest and most enduring.', 'Lighter and more citrus-forward than a Collins - shaken to a silky froth, then lifted with a short soda top.', 'Add gin, lemon juice, and syrup to a shaker with ice. Shake vigorously for 15 seconds. Strain into a chilled highball glass with no ice. Top with a small splash of soda. Garnish with a lemon wheel.', 'Fresh'),
  ('empress-tonic', 'Empress & Tonic', 'cocktail', 'Gin', array['Refreshing', 'Simple']::text[], array['Copa', 'Wine glass', 'Highball']::text[], array['Lime wheel & lavender sprig', 'Lime wheel', 'Grapefruit slice']::text[], 'Gin & tonic was popularised by British colonial officers in 19th century India who mixed quinine (tonic) with gin to make their anti-malarial medicine more palatable.', 'Empress 1908 turns a magical lavender-indigo as it meets tonic - visually stunning and effortlessly elegant.', 'Fill a large wine glass or balloon glass with ice. Add lime juice. Pour gin over ice. Slowly top with chilled tonic water to preserve bubbles. Garnish with a lime wheel and a sprig of lavender if available.', 'Chill'),
  ('scotch-highball', 'Scotch Highball', 'cocktail', 'Whisky', array['Classic', 'Simple']::text[], array['Highball']::text[], array['Lemon twist']::text[], 'The highball became the cocktail format of choice in Japan in the 1950s, but Scotch & soda has been a British pub staple since the Victorian era.', 'The simplest way to enjoy Monkey Shoulder - soda opens up the malt and honey notes without masking them.', 'Fill a highball glass with ice. Pour Scotch over ice. Slowly top with chilled soda to preserve carbonation. Stir once gently. Garnish with a lemon twist.', 'Chill'),
  ('scotch-manhattan', 'Scotch Manhattan', 'cocktail', 'Whisky', array['Signature', 'Spirit-Forward']::text[], array['Coupe', 'Nick & Nora']::text[], array['Lemon twist', 'Orange twist', 'Cocktail cherry']::text[], 'The Manhattan emerged in New York in the 1880s. This Scotch variation - sometimes called a Rob Roy''s cousin - brings honeyed malt in place of rye''s spice.', 'Silky and spirit-forward, with Monkey Shoulder''s malt depth balanced by herbal vermouth and bitters.', 'Add all ingredients to a mixing glass with ice. Stir for 30 seconds until well chilled and diluted. Strain into a chilled coupe. Garnish with a lemon or orange twist.', 'Bold'),
  ('irish-whiskey-sour', 'Irish Whiskey Sour', 'cocktail', 'Whisky', array['Classic', 'Citrus']::text[], array['Rocks', 'Coupe']::text[], array['Lemon wheel', 'Lemon wheel & cherry']::text[], 'Whiskey sours have been enjoyed since the 1860s. Irish whiskey''s natural sweetness and light pot still character makes it a particularly harmonious base.', 'Softer and rounder than its Scotch cousin - Red Breast''s fruit-forward character sings with citrus and rich demerara.', 'Add all ingredients to a shaker with ice. Shake vigorously for 15 seconds. Strain into a rocks glass over ice. Garnish with a lemon wheel. Optional: a dash of Angostura on top.', 'Cosy'),
  ('irish-old-fashioned', 'Irish Old Fashioned', 'cocktail', 'Whisky', array['Signature', 'Spirit-Forward']::text[], array['Rocks']::text[], array['Orange peel', 'Orange peel & cherry']::text[], 'Red Breast 12 is one of Ireland''s finest single pot still whiskeys. Paired with the depth of demerara and the warmth of bitters, this is a contemplative evening drink.', 'Lush, warming, and complex - Red Breast''s orchard fruit and spice elevated by caramel syrup and a hint of chocolate.', 'Combine syrup and both bitters in a mixing glass. Add whiskey and a large handful of ice. Stir 30 rotations. Strain over a large ice cube in a rocks glass. Express an orange peel over the glass.', 'Cosy'),
  ('cosmopolitan', 'Cosmopolitan', 'cocktail', 'Vodka', array['Signature', 'Fruity']::text[], array['Martini', 'Coupe']::text[], array['Lemon twist', 'Flamed orange peel', 'Lime wheel']::text[], 'Popularised in the late 1980s New York bar scene and immortalised by Sex and the City, the Cosmopolitan became the defining cocktail of the 1990s.', 'A blush-pink classic - citrus vodka, Cointreau, and tart pomegranate with a bright lime finish. Elegant and dangerously drinkable.', 'Add all ingredients to a shaker filled with ice. Shake hard for 12 seconds. Double strain into a chilled martini glass. Garnish with a lemon twist or a flamed orange peel.', 'Party'),
  ('vodka-collins', 'Vodka Collins', 'cocktail', 'Vodka', array['Classic', 'Highball']::text[], array['Collins', 'Highball']::text[], array['Lemon slice', 'Lemon slice & cherry']::text[], 'The Collins template - spirit, citrus, sugar, soda - works beautifully with vodka, creating a crisp, neutral canvas that lets the citrus shine.', 'Clean, crisp, and endlessly refreshing. The vodka Collins lets lemon and soda do the talking.', 'Shake vodka, lemon, and syrup with ice. Strain into a tall glass over ice. Top with soda. Stir gently. Garnish with a lemon slice.', 'Fresh'),
  ('moscow-mule', 'Moscow Mule', 'cocktail', 'Vodka', array['Classic', 'Highball']::text[], array['Copper mug', 'Rocks', 'Highball']::text[], array['Lime wheel', 'Lime wheel & mint sprig']::text[], 'Invented in 1941 in Hollywood by John Martin (Smirnoff) and Jack Morgan (Cock ''n'' Bull ginger beer) to sell two slow-moving products. The copper mug became iconic.', 'Sharp, spicy ginger beer meeting clean vodka and bright lime over crushed ice - a crowd-pleaser that never goes out of style.', 'Fill a copper mug (or rocks glass) with crushed ice. Add lime juice and vodka. Top with chilled ginger beer. Stir gently. Garnish with a lime wheel and mint sprig.', 'Party'),
  ('tequila-mule', 'Tequila Mule', 'cocktail', 'Tequila', array['Citrus', 'Highball']::text[], array['Copper mug', 'Highball']::text[], array['Lime wheel', 'Lime wedge']::text[], 'A Mexican-inspired twist on the Moscow Mule, replacing vodka with tequila. The añejo''s aged complexity adds a smoky, caramel depth the original can''t match.', 'Ginger''s heat meets tequila''s agave soul with bright lime - bolder and earthier than the original Mule.', 'Fill a copper mug or highball glass with crushed ice. Add lime juice and tequila. Top with ginger beer. Stir once. Garnish with a lime wheel.', 'Bold'),
  ('scottish-mule', 'Scottish Mule', 'cocktail', 'Whisky', array['Highball', 'Spirit-Forward']::text[], array['Highball', 'Copper mug']::text[], array['Lime wedge']::text[], 'Scotland meets Moscow - a bold riff that plays Monkey Shoulder''s honeyed vanilla and malt against the punch of ginger beer and citrus.', 'Earthy, spiced, and warming - ginger amplifies the whisky''s natural spice while lime cuts through its depth.', 'Build lime juice and Scotch over ice in a highball glass. Top with ginger beer. Add a dash of bitters. Stir gently. Garnish with a lime wedge.', 'Bold'),
  ('pomegranate-margarita', 'Pomegranate Margarita', 'cocktail', 'Tequila', array['Citrus', 'Fruity', 'Signature']::text[], array['Rocks', 'Coupe']::text[], array['Salt rim & lime wheel', 'Pomegranate seeds']::text[], 'A modern riff on the classic margarita, the pomegranate variation became popular in the 2000s as exotic fruit juices entered mainstream cocktail culture.', 'Deep ruby-red and vibrant - classic margarita character with a jewel-toned, antioxidant-rich twist.', 'Rim a rocks glass with salt. Add all ingredients to a shaker with ice. Shake vigorously 12 seconds. Strain into the prepared glass over fresh ice. Garnish with a lime wheel.', 'Party'),
  ('clover-club-pomegranate', 'Clover Club (Pomegranate)', 'cocktail', 'Gin', array['Fruity', 'Classic']::text[], array['Coupe']::text[], array['Lemon twist', 'Pomegranate seeds']::text[], 'The Clover Club pre-dates Prohibition, created for a Philadelphia gentlemen''s club of the same name. This version swaps raspberries for pomegranate - equally tart, more striking.', 'Silky and pink, with floral gin lifting tart lemon and pomegranate into something genuinely beautiful.', 'Combine all ingredients in a shaker without ice. Dry shake 10 seconds. Add ice and shake hard 15 seconds. Double strain into a chilled coupe. Garnish with a lemon twist.', 'Romantic'),
  ('tequila-collins', 'Tequila Collins', 'cocktail', 'Tequila', array['Citrus', 'Highball']::text[], array['Collins', 'Highball']::text[], array['Lemon slice', 'Lime wheel']::text[], 'The Collins template applied to tequila creates a surprisingly harmonious long drink - the agave character adds a herbaceous, earthy layer not found in the gin or vodka versions.', 'A tall, sunlit drink - aged tequila''s warmth stretched with citrus and soda into something surprisingly delicate.', 'Shake tequila, lemon, and syrup with ice. Strain into a tall glass over ice. Top with soda. Stir gently. Garnish with a lemon slice.', 'Fresh'),
  ('rum-sour', 'Rum Sour', 'cocktail', 'Rum', array['Classic', 'Citrus']::text[], array['Rocks', 'Coupe']::text[], array['Lemon wheel & bitters dash', 'Lemon wheel']::text[], 'Sours are one of the oldest cocktail families, dating to the 1850s. Dark rum''s molasses depth and natural sweetness make it a particularly well-suited base.', 'Rich and rounded - the rum''s caramel notes play beautifully against bright lemon and the depth of demerara.', 'Add all ingredients to a shaker with ice. Shake vigorously 15 seconds. Strain into a rocks glass over ice. Garnish with a lemon wheel and a dash of bitters on top.', 'Cosy'),
  ('mojito-royale', 'Mojito Royale', 'cocktail', 'Rum', array['Signature', 'Sparkling']::text[], array['Wine glass', 'Flute']::text[], array['Mint crown & lime wheel']::text[], 'A champagne-elevated take on the Cuban Mojito - the prosecco lifts the cocktail from beach bar to dinner party in one elegant pour.', 'A sophisticated, celebratory mojito - same rum, mint, and lime soul, crowned with sparkling prosecco.', 'Muddle mint with lime juice and syrup in a wine glass. Fill with crushed ice. Add rum. Top with chilled Prosecco. Stir gently. Garnish with a mint crown and lime wheel.', 'Party'),
  ('scotch-julep', 'Scotch Julep', 'cocktail', 'Whisky', array['Signature', 'Spirit-Forward']::text[], array['Julep cup', 'Rocks']::text[], array['Mint bouquet', 'Mint bouquet & powdered sugar']::text[], 'The Mint Julep is the official cocktail of the Kentucky Derby, made with bourbon. Swapping Monkey Shoulder creates a smoky, honeyed Scottish cousin equally worthy of a warm evening.', 'Crushed ice, heady fresh mint, and the golden warmth of Monkey Shoulder - contemplative, aromatic, and deeply satisfying.', 'Gently muddle mint with syrup in a julep cup or rocks glass. Fill with crushed ice. Pour Scotch over ice. Stir briefly to combine. Pack with more crushed ice. Garnish generously with a mint bouquet. Dust with powdered sugar if desired.', 'Cosy'),
  ('rum-fizz', 'Rum Fizz', 'cocktail', 'Rum', array['Refreshing', 'Effervescent']::text[], array['Highball']::text[], array['Lemon slice']::text[], 'The Fizz format - shaken spirit, citrus, sugar, and soda - works beautifully with dark rum, creating a tropical-leaning drink with a long effervescent finish.', 'Bright and bubbly - rum''s molasses depth lifted by lemon and soda into a light, effervescent crowd-pleaser.', 'Shake rum, lemon, and syrup hard with ice. Strain into a chilled highball glass with no ice. Top with soda to create a frothy top. Garnish with a lemon slice.', 'Fresh'),
  ('pomegranate-gin-sour', 'Pomegranate Gin Sour', 'cocktail', 'Gin', array['Fruity', 'Signature']::text[], array['Coupe']::text[], array['Lemon twist', 'Pomegranate seeds']::text[], 'A modern creation that plays Empress 1908''s butterfly pea flower botanicals against tart pomegranate - the colours swirl together dramatically in the glass.', 'Jewel-toned and arresting - floral gin, tart pomegranate, and citrus in a perfectly balanced sour.', 'Add all ingredients to a shaker with ice. Shake vigorously 15 seconds. Double strain into a chilled coupe. The Empress gin and pomegranate will create a deep rose hue. Garnish with a lemon twist.', 'Romantic'),
  ('bittersweet-scotch', 'Bittersweet Scotch', 'cocktail', 'Whisky', array['Spirit-Forward', 'Signature']::text[], array['Coupe', 'Nick & Nora']::text[], array['Orange peel']::text[], 'A contemporary creation inspired by the Scotch Dry Martini - using Glenfiddich''s fruity, light character alongside a touch of blanc vermouth and chocolate bitters.', 'Delicately bitter and silky - Glenfiddich''s pear and vanilla meet herbal vermouth with a lingering chocolate finish.', 'Add all ingredients to a mixing glass with ice. Stir 30 seconds until very cold. Strain into a chilled coupe. Express a lemon peel over the drink and discard. Garnish with orange peel.', 'Curious'),
  ('tequila-fizz', 'Tequila Fizz', 'cocktail', 'Tequila', array['Citrus', 'Refreshing']::text[], array['Highball']::text[], array['Lime wheel']::text[], 'A bright, effervescent take on tequila that lets the aged agave breathe through the bubbles. Popular in Mexico City''s modern cocktail bars.', 'The margarita''s refreshing cousin - shaken tequila and lime topped with soda for a lighter, longer drink.', 'Shake tequila, lime, and syrup hard with ice. Strain into a chilled highball glass without ice. Add soda gently to preserve fizz. Garnish with a lime wheel.', 'Fresh'),
  ('whiskey-collins', 'Whiskey Collins', 'cocktail', 'Whisky', array['Classic', 'Highball']::text[], array['Collins', 'Highball']::text[], array['Lemon slice', 'Lemon slice & mint sprig']::text[], 'Applying the Collins template to Irish whiskey creates a long drink of unusual elegance - Red Breast''s pot still character adds a creamy, orchard-fruit depth.', 'A gentle giant - Red Breast''s complex fruit and spice stretched into a long, summery Collins.', 'Shake whiskey, lemon, and syrup with ice. Strain into a tall glass over ice. Top with soda. Stir gently. Garnish with a lemon slice and mint if desired.', 'Fresh'),
  ('rum-cooler', 'Rum Cooler', 'cocktail', 'Rum', array['Refreshing', 'Simple']::text[], array['Highball', 'Collins']::text[], array['Lime wedge']::text[], 'Simple rum-lime-soda combinations have been enjoyed across the Caribbean for centuries - the original rum cooler predates the mojito and is arguably more honest.', 'Stripped back and honest - rum, lime, a breath of demerara, and soda. No frills, full flavour.', 'Build rum, lime, and syrup in a highball glass over ice. Stir to combine. Top with soda. Garnish with a lime wedge.', 'Chill'),
  ('naked-famous-home-bar-edit', 'Naked & Famous (Home Bar Edit)', 'cocktail', 'Tequila', array['Spirit-Forward', 'Bold']::text[], array['Coupe']::text[], array[]::text[], 'Inspired by Sam Ross''s 2011 Naked & Famous (which uses Aperol and mezcal), this version works with what''s behind your bar - bittersweet cocoa bitters stand in for Aperol''s orange-bitter character.', 'Equal-parts and perfectly balanced - tequila, orange liqueur, citrus, and a bittersweet cocoa finish.', 'Add all ingredients to a shaker with ice. Shake hard 12 seconds. Double strain into a chilled coupe. No garnish needed - the drink speaks for itself.', 'Curious'),
  ('rum-punch', 'Rum Punch', 'cocktail', 'Rum', array['Signature', 'Fruity', 'Party']::text[], array['Collins', 'Highball']::text[], array['Lime wheel & mint sprig', 'Orange slice']::text[], 'Caribbean rum punch follows the ancient ''one of sour, two of sweet, three of strong, four of weak'' formula - a recipe documented as far back as 1694 in Barbados.', 'Vivid, tropical, and celebratory - dark rum''s depth carrying layers of citrus and fruit in every sip.', 'Combine all ingredients in a shaker with ice. Shake 10 seconds. Strain into a tall glass over ice. Garnish with a lime wheel and mint sprig. Optional: float a little dark rum on top.', 'Party'),
  ('negroni-bianco', 'Negroni Bianco', 'cocktail', 'Gin', array['Italian Classic', 'Aperitif']::text[], array['Rocks']::text[], array['Lemon peel']::text[], 'A white Negroni variation using blanc vermouth instead of Campari and sweet vermouth - a lighter, more floral interpretation that originated in Bordeaux in the early 2000s.', 'Paler and more delicate than the original - Empress gin''s floral botanicals bloom through the vermouth with a bitter whisper from both bitters.', 'Add all ingredients to a mixing glass with ice. Stir 30 seconds. Strain into a rocks glass over a large ice cube. Express a lemon peel over the glass and use as garnish.', 'Curious'),
  ('amaretto-spritz', 'Amaretto Spritz', 'cocktail', 'Amaretto', array['Nutty', 'Sparkling']::text[], array['Wine glass']::text[], array['Lemon slice', 'Orange slice']::text[], 'Aperol Spritz''s nutty, marzipan-forward cousin - using Disaronno in place of Aperol creates a sweeter, more warming spritz ideal for cooler evenings.', 'Sparkling, nutty, and gently sweet - Disaronno''s almond warmth lifted by Prosecco bubbles and a squeeze of lemon.', 'Add ice to a large wine glass. Pour amaretto and lemon juice over ice. Top slowly with chilled Prosecco. Stir once gently. Garnish with a lemon slice.', 'Chill'),
  ('lime-daisy-tequila', 'Lime Daisy (Tequila)', 'cocktail', 'Tequila', array['Citrus', 'Signature']::text[], array['Highball']::text[], array['Lime wheel']::text[], 'The Daisy - spirit, citrus, orange liqueur, topped with soda - predates the Margarita and may actually be its direct ancestor. ''Margarita'' is Spanish for daisy.', 'Essentially the missing link between a Margarita and a Collins - longer, lighter, and endlessly refreshing.', 'Shake tequila, Cointreau, lime, and syrup with ice. Strain into a highball glass over ice. Add a splash of soda. Garnish with a lime wheel.', 'Fresh'),
  ('scotch-sour-cocoa-twist', 'Scotch Sour (Cocoa Twist)', 'cocktail', 'Whisky', array['Spirit-Forward', 'Signature']::text[], array['Rocks', 'Coupe']::text[], array['Lemon wheel']::text[], 'A riff on the classic Whisky Sour that uses Angostura Cocoa Bitters as both an aromatic and a flavour bridge between Glenfiddich''s fruity character and the citrus.', 'A whisky sour with a moody undercurrent - the cocoa bitters add a dry, bittersweet layer that makes the lemon pop.', 'Add Scotch, lemon, and syrup to a shaker with ice. Shake hard 15 seconds. Strain into a rocks glass over ice. Float cocoa bitters on the surface. Garnish with a lemon wheel.', 'Cosy'),
  ('boulevardier', 'Boulevardier', 'cocktail', 'Whisky', array['Italian Classic', 'Spirit-Forward']::text[], array['Coupe', 'Rocks']::text[], array['Orange peel', 'Lemon peel']::text[], 'Created in 1927 by Erskine Gwynne, an American writer living in Paris who ran a literary magazine called ''Boulevardier''. A whisky-forward cousin of the Negroni that swaps gin for whiskey.', 'A Negroni with backbone — Monkey Shoulder''s honeyed malt adds a warming, spiced depth to Campari''s bitter edge. Note: Classic spec uses bourbon + sweet vermouth; this Scotch + Dolin Dry version is softer and more floral.', 'Add all ingredients to a mixing glass with ice. Stir for 30 seconds until well chilled. Strain into a chilled coupe (or a rocks glass over a large ice cube). Express an orange peel over the drink and garnish.', 'Cosy'),
  ('old-pal', 'Old Pal', 'cocktail', 'Whisky', array['Spirit-Forward', 'Classic']::text[], array['Coupe', 'Nick & Nora']::text[], array['Lemon twist']::text[], 'Documented in Harry McElhone''s 1922 ''Harry''s ABC of Mixing Cocktails'' at Harry''s New York Bar in Paris. The drier, more bracing sibling of the Boulevardier — equal parts whisky, Campari, and DRY vermouth.', 'Bracing and dry — unlike the Boulevardier, this one is built for Dolin Dry. Campari''s bitterness meets whisky''s warmth with a crisp, herbal finish. Perfect use of your Dolin Dry/Blanc.', 'Add all ingredients to a mixing glass with ice. Stir 30 seconds until well chilled. Strain into a chilled coupe. Garnish with a lemon twist.', 'Bold'),
  ('campari-spritz', 'Campari Spritz', 'cocktail', 'Campari', array['Italian Classic', 'Aperitif', 'Sparkling']::text[], array['Wine glass']::text[], array['Orange slice']::text[], 'The original Italian spritz, predating the ubiquitous Aperol Spritz. The classic 3-2-1 format (3 parts Prosecco, 2 parts Campari, 1 splash soda) has been enjoyed across Italy since the early 1900s.', 'Brighter, more bitter, and more complex than an Aperol Spritz — Campari''s herbal punch cuts through the Prosecco''s sweetness for the ultimate Italian aperitivo.', 'Fill a large wine glass with ice. Add Campari. Top with chilled Prosecco. Finish with a splash of soda. Stir once gently. Garnish with an orange slice.', 'Chill'),
  ('negroni-sbagliato', 'Negroni Sbagliato', 'cocktail', 'Campari', array['Italian Classic', 'Aperitif', 'Sparkling']::text[], array['Rocks', 'Wine glass']::text[], array['Orange half-wheel', 'Orange slice']::text[], 'Created by accident in Milan''s Bar Basso in the 1970s when bartender Mirko Stocchetto reached for Prosecco instead of gin. ''Sbagliato'' means ''mistaken'' in Italian — a mistake that became a classic.', 'A lighter, effervescent Negroni — Prosecco''s bubbles open up Campari''s bitterness into something elegant and sessionable. Traditional recipe uses sweet vermouth; Dolin Dry makes it more floral.', 'Add Campari and vermouth to a rocks glass with a large ice cube. Top with chilled Prosecco. Stir gently once. Garnish with an orange slice or half-wheel.', 'Chill'),
  ('garibaldi', 'Garibaldi', 'cocktail', 'Campari', array['Italian Classic', 'Aperitif', 'Refreshing']::text[], array['Highball']::text[], array['Orange wedge', 'Orange slice']::text[], 'Named after Giuseppe Garibaldi, the Italian general who unified the country. The drink symbolises the union of northern Italy (Campari, from Milan) and southern Italy (oranges, from Sicily). Bar Dante in NYC elevated it with ''fluffy'' whipped orange juice.', 'Deceptively simple — just two ingredients, but when the orange juice is fresh and frothy, the result is magic. Campari''s bitter edge tamed by bright citrus.', 'Fill a highball glass with ice. Add Campari. Top with fresh, vigorously-shaken orange juice (shake OJ alone in a shaker 30 sec for frothiness). Garnish with an orange wedge.', 'Fresh'),
  ('jasmine', 'Jasmine', 'cocktail', 'Gin', array['Citrus', 'Modern Classic']::text[], array['Coupe', 'Martini']::text[], array['Lemon twist']::text[], 'Created in the early 1990s by bartender Paul Harrington in Emeryville, California. A modern classic disguised as a pink cocktail — the small amount of Campari transforms the colour and adds complexity.', 'Looks like a Cosmopolitan, drinks like a Negroni meets a White Lady. A stunning balance of bitter, sweet, and citrus — pink, elegant, and deceptively complex.', 'Add all ingredients to a shaker with ice. Shake hard for 12 seconds. Double strain into a chilled coupe. Garnish with a lemon twist.', 'Curious'),
  ('rosita', 'Rosita', 'cocktail', 'Tequila', array['Spirit-Forward', 'Signature']::text[], array['Rocks']::text[], array['Grapefruit twist', 'Orange twist']::text[], 'Documented by Gary Regan in the 1991 ''Bartender''s Bible'' — a tequila-based Negroni variation that showcases how beautifully aged agave works with Campari''s bitter herbs.', 'The smoky, earthy tequila cousin of the Negroni. Añejo''s caramel and oak layers weave through Campari''s bitterness with herbal vermouth and warming bitters.', 'Add all ingredients to a mixing glass with ice. Stir 30 seconds until well chilled. Strain into a rocks glass over a large ice cube. Garnish with a grapefruit or orange twist.', 'Bold'),
  ('campari-sour', 'Campari Sour', 'cocktail', 'Campari', array['Citrus', 'Aperitif']::text[], array['Rocks', 'Coupe']::text[], array['Orange slice', 'Lemon wheel']::text[], 'A simple, modern Italian creation that treats Campari as the base spirit of a classic sour. Low-ABV but packed with flavour — perfect for those who love the Negroni but want something lighter and brighter.', 'Ruby red, tart, and refreshing — Campari''s herbal bitterness balanced perfectly by bright lemon and a kiss of sweetness.', 'Add all ingredients to a shaker with ice. Shake hard 12 seconds. Strain into a rocks glass over fresh ice. Garnish with an orange slice or lemon wheel.', 'Fresh'),
  ('dark-n-stormy', 'Dark ''n Stormy', 'cocktail', 'Rum', array['Highball', 'Refreshing']::text[], array['Highball']::text[], array['Lime wedge', 'Lime wheel']::text[], 'The national drink of Bermuda, created when British Royal Navy sailors mixed their local Gosling''s Black Seal rum with ginger beer. The name comes from a sailor who said the drink was ''the colour of a cloud only a fool or a dead man would sail under''.', 'A stormy, spicy, unapologetically rum-forward highball. Dark rum''s molasses depth meets the bite of ginger beer with a lime squeeze to balance.', 'Fill a highball glass with ice. Add lime juice. Pour dark rum over ice. Top with ginger beer. Do NOT stir — let the rum swirl down for the stormy effect. Garnish with a lime wedge.', 'Bold'),
  ('gin-buck', 'Gin Buck', 'cocktail', 'Gin', array['Highball', 'Refreshing']::text[], array['Highball']::text[], array['Lemon wedge']::text[], 'The ''Buck'' family of cocktails — spirit + citrus + ginger beer — dates to the early 1900s. The Gin Buck (sometimes called a London Buck) predates the Moscow Mule and is arguably its direct ancestor.', 'A long, spicy refresher — Empress gin''s floral character lifted by the sharp kick of ginger and a bright lemon squeeze. Lighter and more aromatic than a Mule.', 'Fill a highball glass with ice. Add gin and lemon juice. Top with chilled ginger beer. Stir gently once. Garnish with a lemon wedge.', 'Fresh'),
  ('hot-toddy', 'Hot Toddy', 'cocktail', 'Whisky', array['Hot Drink', 'Cosy']::text[], array['Heatproof mug', 'Toddy glass']::text[], array['Clove-studded lemon wheel & cinnamon stick', 'Lemon wheel']::text[], 'Hot Toddies have been served in Scotland and Ireland since at least the 1780s as both a social drink and a cold remedy. The name likely comes from ''toddy'', a fermented palm-sap drink from India brought back by British soldiers.', 'The ultimate cold-weather cocktail — Red Breast''s orchard-fruit warmth amplified by hot water, with lemon to cut through and demerara to round out. Traditional cold cure, traditional soul warmer.', 'Warm a heatproof mug with hot water, then empty. Add whiskey, demerara syrup, and lemon juice. Top with hot (not boiling) water. Stir once. Garnish with a lemon wheel studded with cloves and a cinnamon stick if available.', 'Cosy'),
  ('mamie-taylor', 'Mamie Taylor', 'cocktail', 'Whisky', array['Highball', 'Refreshing']::text[], array['Highball']::text[], array['Lime wedge', 'Lime wedge & mint sprig']::text[], 'Named for American opera singer Mamie Taylor, invented in 1899 on a hot summer day in Rochester, NY when she asked for ''something tall and refreshing'' and the bartender improvised with Scotch, lime, and ginger beer. Ran of the day''s hottest drinks before the Moscow Mule eclipsed it.', 'Scotch''s forgotten highball — smoky, honeyed malt lengthened with fresh lime and a lively ginger kick. Elegant, balanced, and dangerously easy to drink.', 'Fill a highball glass with ice. Add Scotch and lime juice. Top with chilled ginger beer. Stir gently. Garnish with a lime wedge and a sprig of mint if available.', 'Fresh'),
  ('hugo-spritz', 'Hugo Spritz', 'cocktail', 'Prosecco', array['Italian Classic', 'Aperitif', 'Sparkling']::text[], array['Wine glass']::text[], array['Mint sprig & lime wheel']::text[], 'Created in 2005 by bartender Roland Gruber in Naturno, in the Italian Alps'' South Tyrol region. Originally made with elderflower syrup, St-Germain became the preferred ingredient. Now ubiquitous across Northern Italy as the lighter, floral cousin to the Aperol Spritz.', 'Light, floral, and gloriously refreshing — elderflower''s honeyed notes lifted by Prosecco bubbles and fresh mint. Lower in alcohol and far more delicate than an Aperol Spritz.', 'Gently slap a handful of mint between your palms to release the oils. Add to a large wine glass with ice. Add St-Germain and lime juice. Top with chilled Prosecco. Finish with a splash of soda. Stir gently once. Garnish with a fresh mint sprig and a lime wheel.', 'Chill'),
  ('saint-germain-cocktail', 'Saint-Germain Cocktail', 'cocktail', 'Prosecco', array['Aperitif', 'Sparkling', 'Signature']::text[], array['Collins', 'Flute']::text[], array['Long lemon twist']::text[], 'The signature cocktail printed on the back of every St-Germain bottle — created by the brand itself when the liqueur launched in 2007. A simple template that introduced elderflower liqueur to a generation of drinkers.', 'Elegant and effervescent — equal-parts sparkling wine and elderflower, dressed with a whisper of lemon. The cocktail that put St-Germain on the map.', 'Fill a tall collins glass or flute with ice. Add St-Germain and lemon juice. Top with chilled Prosecco. Finish with a splash of soda. Stir gently. Garnish with a long lemon twist.', 'Romantic'),
  ('elderflower-martini', 'Elderflower Martini', 'cocktail', 'Gin', array['Signature', 'Floral']::text[], array['Coupe', 'Martini']::text[], array['Lemon twist', 'Edible flower']::text[], 'A modern classic that emerged in mid-2000s cocktail bars as St-Germain swept through the craft cocktail scene. The Empress 1908 + elderflower pairing has become a signature for botanical-forward bars.', 'Floral, citrus-bright, and stunning — Empress gin''s lavender hue meets elderflower''s honeyed sweetness. The lemon cuts through to keep it balanced and bracing.', 'Add all ingredients to a shaker with ice. Shake hard 12 seconds. Double strain into a chilled coupe or martini glass. Garnish with a lemon twist or an edible flower.', 'Romantic'),
  ('elderflower-collins', 'Elderflower Collins', 'cocktail', 'Gin', array['Highball', 'Refreshing', 'Floral']::text[], array['Collins']::text[], array['Lemon wheel & mint sprig', 'Lemon wheel & edible flower']::text[], 'A modern riff on the Tom Collins, swapping simple syrup for St-Germain. The combination of gin, citrus, and elderflower has become one of the most popular long-drink templates in contemporary bars.', 'A long, floral, garden-fresh refresher — gin''s botanicals dance with elderflower honey, brightened by lemon and lifted by soda.', 'Add gin, St-Germain, and lemon juice to a shaker with ice. Shake 10 seconds. Strain into a tall Collins glass over ice. Top with chilled soda. Stir gently. Garnish with a lemon wheel and a sprig of mint or an edible flower.', 'Fresh'),
  ('empress-elderflower-spritz', 'Empress Elderflower Spritz', 'cocktail', 'Gin', array['Signature', 'Sparkling', 'Floral']::text[], array['Wine glass']::text[], array['Lime wheel & mint sprig']::text[], 'A modern home-bar creation that puts two showstopper ingredients in the same glass — Empress 1908''s colour-shift and St-Germain''s floral sweetness. The result is visually stunning and aromatically complex.', 'A magenta spritz with serious botanical depth — Empress gin shifts to a soft pink against the lemon-tinted base, while elderflower adds floral honey notes against the crisp Prosecco.', 'Fill a large wine glass with ice. Add gin, St-Germain, and lime juice. Top with chilled Prosecco and finish with a splash of soda. Stir gently. Garnish with a lime wheel and a sprig of mint.', 'Romantic'),
  ('elderflower-margarita', 'Elderflower Margarita', 'cocktail', 'Tequila', array['Citrus', 'Signature', 'Floral']::text[], array['Coupe', 'Rocks']::text[], array['Lime wheel', 'Salt rim & lime wheel']::text[], 'A modern variation on the classic Margarita popularised in the 2010s. The St-Germain rounds out the sharp citrus with a delicate floral sweetness — a far gentler, more aromatic Margarita.', 'A softer, more elegant Margarita — añejo tequila''s caramel depth meets elderflower''s floral honey, balanced by Cointreau and bright lime. Less aggressive, more romantic.', 'Optional: rim a coupe with salt. Add all ingredients to a shaker with ice. Shake hard 12 seconds. Double strain into the prepared coupe or a rocks glass over fresh ice. Garnish with a lime wheel.', 'Romantic'),
  ('floradora', 'Floradora', 'cocktail', 'Gin', array['Highball', 'Fruity']::text[], array['Collins', 'Highball']::text[], array['Lime wedge & pomegranate seeds', 'Lime wedge']::text[], 'Created at the Hotel Cecil in London in 1899 to celebrate the hit Broadway musical ''Floradora''. Traditionally made with raspberry syrup — this modern riff uses pomegranate and St-Germain for added depth and complexity.', 'Pretty, pink, and spicy — gin and floral elderflower meet tart pomegranate and the ginger beer''s kick. A vintage cocktail with a modern, floral upgrade.', 'Add gin, St-Germain, lime juice, and pomegranate juice to a shaker with ice. Shake 10 seconds. Strain into a tall glass over ice. Top with chilled ginger beer. Stir gently. Garnish with a lime wedge and fresh pomegranate seeds if available.', 'Party'),
  ('elderflower-negroni', 'Elderflower Negroni', 'cocktail', 'Gin', array['Italian Classic', 'Signature', 'Floral']::text[], array['Rocks']::text[], array['Orange peel']::text[], 'A modern twist on the classic Negroni that softens Campari''s bitterness with elderflower''s honeyed sweetness. Has become a popular variation in contemporary cocktail bars as a ''gateway Negroni'' for those new to amaro.', 'A floral, friendlier Negroni — St-Germain rounds Campari''s bitter edges into something balanced and aromatic. Empress gin''s botanicals complete the floral chorus.', 'Add all ingredients to a mixing glass with ice. Stir 30 seconds until well chilled. Strain into a rocks glass over a large ice cube. Express an orange peel and garnish.', 'Curious'),
  ('elderflower-whisky-sour', 'Elderflower Whisky Sour', 'cocktail', 'Whisky', array['Citrus', 'Signature']::text[], array['Rocks', 'Coupe']::text[], array['Lemon wheel & bitters dash', 'Lemon wheel']::text[], 'A modern whisky sour variation that emerged in the 2010s — St-Germain replaces or supplements the simple syrup, adding floral complexity to Red Breast''s natural orchard-fruit character.', 'A whisky sour with romance — Red Breast''s creamy pot-still fruit meets elderflower honey and bright lemon, with demerara adding warmth. Sophisticated and easy-drinking.', 'Add all ingredients to a shaker with ice. Shake hard 15 seconds. Strain into a rocks glass over fresh ice. Garnish with a lemon wheel and a dash of Angostura on top.', 'Cosy'),
  ('vodka-elderflower-fizz', 'Vodka Elderflower Fizz', 'cocktail', 'Vodka', array['Highball', 'Refreshing', 'Floral']::text[], array['Collins', 'Highball']::text[], array['Lemon twist', 'Edible flower']::text[], 'Part of the wave of clean, modern vodka highballs that emerged with St-Germain''s popularity in the late 2000s. Designed to let elderflower shine without competing botanicals from gin.', 'Crisp, clean, and floral — vodka''s neutrality lets St-Germain''s honeyed elderflower take centre stage, with citrus and soda for refreshment.', 'Add vodka, St-Germain, and lemon juice to a shaker with ice. Shake 10 seconds. Strain into a tall glass over ice. Top with soda. Stir gently. Garnish with a lemon twist or an edible flower.', 'Fresh'),
  ('gentlemans-knock', 'Gentleman’s Knock', 'cocktail', 'Whisky', array['Spirit-Forward', 'Modern Classic', 'Spicy']::text[], array['Nick & Nora', 'Coupe']::text[], array['Orange twist']::text[], 'A modern riff on the Manhattan built on a 2 : ¾ : ¼ : ¼ home-bar ratio. Sweet vermouth keeps the classic structure, while Bénédictine and Ancho Reyes add herbal and chile layers.', 'Bourbon-forward, herbal, lightly sweet, with baking spice, warm chile, and orange. The bourbon stays the star; Bénédictine adds honeyed herbal complexity without turning syrupy, and Ancho Reyes brings a gentle chile finish.', 'Add all ingredients to a mixing glass filled with ice. Stir 20–30 seconds until very cold and properly diluted. Strain into a chilled Nick & Nora or coupe. Express an orange twist over the surface and garnish.', 'Bold'),
  ('monte-carlo', 'Monte Carlo', 'cocktail', 'Whisky', array['Spirit-Forward', 'Classic']::text[], array['Rocks']::text[], array['Lemon twist']::text[], 'Documented in David Embury’s 1948 ‘The Fine Art of Mixing Drinks’ as a whiskey cocktail sweetened with Bénédictine instead of vermouth. Classic spec uses rye; bourbon makes it rounder.', 'An Old Fashioned’s richer cousin — Bénédictine’s honeyed herbs and baking spice wrap around bourbon, with Angostura keeping it dry and aromatic.', 'Add all ingredients to a mixing glass with ice. Stir 20–30 seconds until well chilled. Strain into a rocks glass over a large ice cube. Express a lemon twist over the drink and garnish.', 'Bold'),
  ('frisco-sour', 'Frisco Sour', 'cocktail', 'Whisky', array['Sour', 'Classic']::text[], array['Coupe']::text[], array['Lemon twist']::text[], 'A classic whiskey sour variation named for San Francisco, where Bénédictine replaces the sugar and a split of lemon and lime sharpens the citrus.', 'A whiskey sour with herbal depth — Bénédictine brings honey and spice in place of syrup, while lemon and lime keep it bright and dry.', 'Add all ingredients to a shaker with ice. Shake hard 12–15 seconds. Strain into a chilled coupe. Garnish with a lemon twist.', 'Curious'),
  ('whiskey-smash', 'Whiskey Smash', 'cocktail', 'Whisky', array['Refreshing', 'Classic']::text[], array['Rocks', 'Julep cup']::text[], array['Mint sprig', 'Mint sprig & lemon wedge']::text[], 'The Smash appears in Jerry Thomas’s 1862 bar guide as a smaller julep. Dale DeGroff’s lemon-and-mint Whiskey Smash revived it for the modern cocktail bar in the 2000s.', 'Bright, minty, and easy-drinking — bourbon’s vanilla warmth meets fresh lemon and cooling mint over crushed ice. A julep with a citrus kick.', 'Gently muddle the mint with the simple syrup in a shaker. Add bourbon, lemon juice, and ice. Shake 10–12 seconds. Strain into a rocks glass over crushed ice. Garnish with a mint sprig.', 'Fresh'),
  ('spicy-ancho-margarita', 'Spicy Ancho Margarita', 'cocktail', 'Tequila', array['Margarita', 'Spicy', 'Modern Classic']::text[], array['Rocks', 'Coupe']::text[], array['Salt rim & lime wheel', 'Tajín rim & lime wheel']::text[], 'Ancho Reyes, a Puebla-style chile liqueur based on a 1927 recipe, launched in 2014 and quickly became the bartender’s shortcut to a spicy Margarita without muddling fresh peppers.', 'A Margarita with a slow, smoky warmth — Añejo’s oak and vanilla meet Ancho Reyes’ dried-chile heat, with Cointreau and lime keeping it bright.', 'Rim a rocks glass with salt. Add all ingredients to a shaker with ice. Shake hard 12–15 seconds. Strain into the glass over fresh ice. Garnish with a lime wheel.', 'Party'),
  ('daiquiri', 'Daiquiri', 'cocktail', 'Rum', array['Classic', 'Sour']::text[], array['Coupe']::text[], array['Lime wheel']::text[], 'A Cuban classic from the 1890s, named after a beach near Santiago de Cuba.', 'The purest expression of rum, lime, and sugar — bright, clean, and balanced.', 'Add all ingredients to a shaker with ice. Shake hard until well chilled. Double-strain into a chilled coupe. Garnish with a lime wheel.', 'Fresh'),
  ('whiskey-sour', 'Whiskey Sour', 'cocktail', 'Bourbon', array['Classic', 'Sour']::text[], array['Rocks', 'Coupe']::text[], array['Orange half-wheel & cherry', 'Lemon wheel & cherry']::text[], 'A sour documented since the 1860s; Jerry Thomas printed an early recipe in 1862.', 'Bourbon squared up by fresh lemon and a little sugar — the benchmark sour.', 'Add bourbon, lemon, and syrup to a shaker with ice (for a silky foam, add an egg white and dry-shake first). Shake well and strain over fresh ice in a rocks glass. Garnish with an orange half-wheel and a cherry.', 'Bold'),
  ('manhattan', 'Manhattan', 'cocktail', 'Bourbon', array['Classic', 'Spirit-Forward']::text[], array['Coupe', 'Nick & Nora']::text[], array['Cocktail cherry', 'Orange twist']::text[], 'Born in New York in the 1870s, one of the original vermouth cocktails.', 'Whiskey and sweet vermouth laced with bitters — elegant and spirit-forward.', 'Stir bourbon, sweet vermouth, and bitters with ice until well chilled. Strain into a chilled coupe. Garnish with a cherry.', 'Cosy'),
  ('southside', 'Southside', 'cocktail', 'Gin', array['Classic', 'Refreshing']::text[], array['Coupe']::text[], array['Mint sprig']::text[], 'A Prohibition-era favourite claimed by both Chicago''s South Side and New York''s 21 Club.', 'A minty gin sour — the crisp, spirit-forward cousin of the Mojito.', 'Lightly muddle the mint with the syrup in a shaker. Add gin, lemon, and ice. Shake hard and double-strain into a chilled coupe. Garnish with a mint sprig.', 'Fresh'),
  ('gin-rickey', 'Gin Rickey', 'cocktail', 'Gin', array['Highball', 'Refreshing']::text[], array['Highball']::text[], array['Lime wedge']::text[], 'A Washington, D.C. drink of the 1880s, first made with bourbon before gin took over.', 'Dry, fizzy, and unsweetened — gin and fresh lime lengthened with soda.', 'Build gin and lime juice over ice in a highball glass. Top with soda and stir gently. Garnish with a lime wedge.', 'Fresh'),
  ('corpse-reviver-no-2', 'Corpse Reviver No. 2', 'cocktail', 'Gin', array['Classic', 'Citrus']::text[], array['Coupe']::text[], array['Orange twist']::text[], 'From Harry Craddock''s 1930 Savoy Cocktail Book, which warned that four in swift succession will ''unrevive the corpse.''', 'Equal parts gin, orange, and aromatised wine over an anise whisper — bright and complex.', 'Rinse a chilled coupe with anise bitters (or absinthe) and discard the excess. Shake gin, Cointreau, vermouth, and lemon with ice. Double-strain into the glass. Garnish with an orange twist.', 'Curious'),
  ('golden-autumn', 'Golden Autumn', 'cocktail', 'Vodka', array['Fruity']::text[], array['Coupe', 'Martini']::text[], array['Green-apple fan', 'Lime twist']::text[], 'Added to the IBA''s official roster of New Era Drinks in 2007, a soft vodka aperitif built around orchard-apple sweetness.', 'A gentle vodka-and-vermouth sipper lifted by tart green apple and a whisper of almond, rounded out with house lime cordial.', 'Add all ingredients to a shaker with ice. Shake well for 10 sec. Double-strain into a chilled coupe. Garnish with a thin green-apple fan.', 'Curious'),
  ('bacardi-symphony', 'Bacardi Symphony', 'cocktail', 'Rum', array['Signature']::text[], array['Rocks', 'Coupe']::text[], array['Orange twist']::text[], 'An IBA listing from 2000 that reimagines the Negroni family on a base of light Bacardi rum.', 'A spirit-forward, bittersweet rum aperitif — red bitter and dry vermouth layered with honeyed Bénédictine and a lick of orange.', 'Add all ingredients to a mixing glass with ice. Stir 30 sec until well chilled. Strain over a large cube in a rocks glass (or into a chilled coupe). Garnish with an orange twist.', 'Bold'),
  ('maid-in-cuba', 'Maid in Cuba', 'cocktail', 'Rum', array['Refreshing']::text[], array['Highball', 'Rocks']::text[], array['Cucumber ribbon & mint sprig']::text[], 'A modern Cuban-inspired riff on the Southside and mojito, pairing garden cucumber with an absinthe whisper.', 'Bright white rum shaken with lime, mint and cucumber over an absinthe-rinsed glass, finished with a splash of soda — crisp and herbaceous.', 'Rinse a chilled glass with absinthe and discard the excess. Lightly muddle the cucumber slices and mint with the lime and simple syrup. Add rum and ice, shake 10 sec. Fine-strain over fresh ice. Top with the soda. Garnish with a cucumber ribbon and mint sprig.', 'Fresh'),
  ('virgin-mojito', 'Virgin Mojito', 'mocktail', 'Lime', array['Classic', 'Refreshing']::text[], array['Highball', 'Collins']::text[], array['Mint sprig & lime wheel']::text[], 'The non-alcoholic version of Cuba''s iconic Mojito, popularised in hotel bars across Havana for guests who wanted the experience without the rum. As beloved as the original on humid Caribbean evenings.', 'All the soul of a Mojito minus the rum — bright lime, fresh mint, and a long soda top. Effortlessly cooling.', 'Muddle mint leaves gently with lime juice and simple syrup in a highball glass. Fill with crushed ice. Top with chilled soda. Stir gently from the bottom. Garnish with a mint sprig and a lime wheel.', 'Fresh'),
  ('pomegranate-lemonade', 'Pomegranate Lemonade', 'mocktail', 'Pomegranate', array['Fruity', 'Refreshing']::text[], array['Collins', 'Highball']::text[], array['Lemon wheel & pomegranate seeds', 'Lemon wheel']::text[], 'Pomegranate lemonade has roots in Persian and Mediterranean cuisines where pomegranate juice has been a staple beverage ingredient for millennia. The modern fizzy version is a brunch and summer staple.', 'Jewel-toned and tart — bright lemon balanced by sweet-tart pomegranate, finished with a lively soda lift.', 'Add pomegranate juice, lemon juice, and simple syrup to a shaker with ice. Shake 10 seconds. Strain into a tall glass over ice. Top with soda. Stir gently. Garnish with a lemon wheel and pomegranate seeds.', 'Energised'),
  ('shirley-temple', 'Shirley Temple', 'mocktail', 'Ginger Beer', array['Classic', 'Sweet']::text[], array['Highball', 'Collins']::text[], array['Maraschino cherry & orange slice', 'Maraschino cherry']::text[], 'Named after the child actress Shirley Temple, invented in the 1930s at Chasen''s restaurant in Hollywood (or by Royal Hawaiian bartenders, depending on whom you ask). The classic non-alcoholic ''grown-up'' drink for children — and adults who want to feel young.', 'A pretty, fizzy pink classic — ginger beer''s spice meeting sweet-tart pomegranate (the modern grenadine substitute) with a squeeze of lime.', 'Fill a highball glass with ice. Add pomegranate juice and lime juice. Top with chilled ginger beer. Stir gently. Garnish with a maraschino cherry and an orange slice if available.', 'Party'),
  ('virgin-pomegranate-spritz', 'Virgin Pomegranate Spritz', 'mocktail', 'Pomegranate', array['Sparkling', 'Aperitif']::text[], array['Wine glass']::text[], array['Orange slice & pomegranate seeds']::text[], 'A modern home-bar invention designed to capture the spritz experience without alcohol — tonic''s quinine adds a gentle bitter complexity that mimics aperitivo liqueurs.', 'A jewel-toned non-alcoholic spritz — pomegranate''s tart sweetness brightened by lime, lifted by soda and finished with tonic''s bitter botanicals.', 'Fill a large wine glass with ice. Add pomegranate juice, lime juice, and simple syrup. Top with soda and tonic. Stir gently. Garnish with an orange slice and pomegranate seeds.', 'Chill'),
  ('nojito-royale', 'Nojito Royale', 'mocktail', 'Mint', array['Refreshing', 'Sparkling']::text[], array['Highball']::text[], array['Mint crown & lime wheel']::text[], 'An elevated take on the virgin mojito that adds pomegranate juice for visual drama and a deeper, slightly tart fruit note. Popular in modern bars for designated drivers who still want a celebratory experience.', 'A blush-pink mojito with attitude — mint and lime over crushed ice with a pomegranate twist. Looks like a cocktail, drinks like summer.', 'Muddle mint gently with lime juice and simple syrup in a highball glass. Fill with crushed ice. Add pomegranate juice. Top with soda. Stir from the bottom. Garnish with a mint crown and a lime wheel.', 'Fresh'),
  ('citrus-cooler', 'Citrus Cooler', 'mocktail', 'Citrus', array['Citrus', 'Refreshing']::text[], array['Collins', 'Highball']::text[], array['Orange wheel & lemon twist', 'Orange wheel']::text[], 'A classic three-citrus cooler template that''s existed since the early 20th century soda fountain era. The combination of lemon, lime, and orange produces a more complex citrus profile than any single fruit alone.', 'Brightly citrus and endlessly refreshing — three different citrus juices layered with sweet syrup and a long soda top.', 'Add all citrus juices and simple syrup to a shaker with ice. Shake 10 seconds. Strain into a tall glass over ice. Top with soda. Stir gently. Garnish with an orange wheel and a lemon twist.', 'Energised'),
  ('ginger-lime-fizz', 'Ginger Lime Fizz', 'mocktail', 'Ginger Beer', array['Spicy', 'Refreshing']::text[], array['Copper mug', 'Highball']::text[], array['Mint sprig & lime wedge']::text[], 'A modern non-alcoholic riff on the Moscow Mule template — same spicy ginger, citrus, and crisp finish, just without the vodka.', 'Spicy, tart, and grown-up — ginger beer''s punch with bright lime and a hint of demerara''s caramel depth.', 'Add lime juice and demerara syrup to a copper mug or highball glass. Fill with crushed ice. Top with chilled ginger beer. Stir gently. Garnish with a fresh mint sprig and a lime wedge.', 'Energised'),
  ('cinderella', 'Cinderella', 'mocktail', 'Mixed Fruit', array['Classic', 'Fruity']::text[], array['Collins', 'Highball']::text[], array['Orange wedge & maraschino cherry', 'Orange wedge']::text[], 'A vintage mocktail dating to the 1930s, originally made with pineapple, orange, and lemon juices. The ''Cinderella'' name reflected the idea of a non-alcoholic drink dressed up for the ball.', 'A simple, sunny refresher — orange and lemon balanced by a touch of sweetness and a lively soda lift.', 'Add orange juice, lemon juice, and simple syrup to a shaker with ice. Shake hard 10 seconds. Strain into a tall glass over fresh ice. Top with soda. Garnish with an orange wedge and a maraschino cherry if available.', 'Party'),
  ('virgin-margarita', 'Virgin Margarita', 'mocktail', 'Lime', array['Citrus', 'Classic']::text[], array['Rocks', 'Coupe']::text[], array['Salt rim & lime wheel', 'Lime wheel']::text[], 'The non-alcoholic Margarita has been a beach-bar fixture since the original gained popularity. Orange juice stands in for the orange liqueur, and a splash of soda adds the lift you''d otherwise get from quality tequila.', 'All the citrus snap of a Margarita without the kick — tart lime, sweet orange, balanced by syrup with a salty rim.', 'Optional: rim a rocks glass with salt. Add lime juice, orange juice, and simple syrup to a shaker with ice. Shake hard 10 seconds. Strain into the salted glass over fresh ice. Add a splash of soda. Garnish with a lime wheel.', 'Party'),
  ('pomegranate-mint-cooler', 'Pomegranate Mint Cooler', 'mocktail', 'Pomegranate', array['Refreshing', 'Fruity']::text[], array['Wine glass']::text[], array['Mint sprig & pomegranate seeds']::text[], 'A home-bar original combining the Middle Eastern tradition of pomegranate with the British tradition of tonic. Tonic''s quinine adds a subtle bitter complexity that mimics aperitivo character.', 'Aromatic, complex, and refreshing — pomegranate''s tartness meets mint''s coolness with tonic''s gentle bitter finish.', 'Slap a handful of mint between your palms to release aromas. Add to a wine glass with ice. Add pomegranate juice, lemon juice, and simple syrup. Top with chilled tonic. Stir gently. Garnish with a fresh mint sprig and pomegranate seeds.', 'Chill'),
  ('empress-g-t-virgin', 'Empress G&T (Virgin)', 'mocktail', 'Tonic', array['Refreshing', 'Aperitif']::text[], array['Copa', 'Wine glass']::text[], array['Lime wheel & mint sprig']::text[], 'A non-alcoholic riff on the classic G&T template. Tonic''s quinine provides the bitter botanical complexity normally added by gin, while mint and lime bring brightness.', 'Quietly sophisticated — tonic''s botanical depth lifted by mint, lime, and a whisper of sweetness. The grown-up zero-proof option.', 'Slap mint to release aromas. Fill a large wine glass with ice. Add mint, lime juice, and simple syrup. Top with chilled tonic water. Stir gently once. Garnish with a lime wheel and a fresh mint sprig.', 'Chill'),
  ('rooh-afza-rose-cooler', 'Rooh Afza Rose Cooler', 'mocktail', 'Rose', array['Floral', 'Refreshing', 'Signature']::text[], array['Highball']::text[], array['Mint sprig & lemon slice', 'Edible rose petals']::text[], 'Rooh Afza has been a beloved South Asian summer staple since 1906, traditionally served with cold water or milk during Ramadan iftars. This sparkling, citrus-lifted version is a modern home-bar update.', 'A rose-tinted, cardamom-kissed refresher — Rooh Afza''s iconic floral sweetness brightened by lemon and lifted by soda.', 'Gently slap mint between your palms. Add to a highball glass with ice. Add Rooh Afza and lemon juice. Top with chilled soda. Stir gently. Garnish with a fresh mint sprig and a lemon slice. Optional: edible rose petals.', 'Romantic')
